// Isolated approved-layout integration. A verified provider supplies bearer; never infer identity from the UI.
(()=>{
 let client,records=[],artists=[],busy=false;
 const oldAction=action,oldRender=render,oldReview=reviewPage,oldChecks=checks;
 const oldCatalog=renderCatalog;
 renderCatalog=function(){oldCatalog();const seen=new Set();document.querySelectorAll('.catalog-row').forEach(row=>{const id=row.querySelector('[data-edit]')?.dataset.edit;if(seen.has(id)||!row.querySelector('h3')?.textContent.trim())row.remove();seen.add(id);});document.querySelector('#row-count').textContent=document.querySelectorAll('.catalog-row').length+' 条内容';};
 const uuidLike=id=>/^[0-9a-f-]{36}$/.test(id||'');
 const errors={AUTH_NOT_CONFIGURED:'登录能力尚未配置',UNAUTHENTICATED:'请先登录',FORBIDDEN:'没有操作权限',CONFLICT:'内容已更新，请重新载入后编辑',INVALID_INPUT:'请补齐名称、城市、来源及关联内容',INVALID_MEDIA:'图片格式、尺寸或文件大小不符合要求',NOT_FOUND:'关联内容尚未发布或不存在'};
 const msg=e=>errors[e.code]||'操作未成功，请重试';
 async function locked(work){if(busy)return;busy=true;try{await work();}catch(e){setToast(msg(e));}finally{busy=false;}}
 function artistId(name){const found=artists.filter(r=>r.draft.name===name);if(found.length!==1)throw Object.assign(Error(),{code:'INVALID_INPUT'});return found[0].id;}
 const empty=(kind)=>({id:'new-'+kind,kind:{place:'地点',route:'路线',event:'演出'}[kind],name:'',city:'',artist:artists[0]?.draft.name||'',source:'',description:'',category:'景点',status:'草稿',stops:[],venue:'',date:'',time:'',cover:''});
 function translate(r){const d=r.draft,name=artists.find(a=>a.id===d.artistId||a.id===d.artistEvidence?.artistId||d.artistIds?.includes(a.id))?.draft.name||'';return {id:r.id,version:r.version,kind:{place:'地点',route:'路线',event:'演出'}[r.kind],...d,artist:name,same:d.artistEvidence?.sameSpot||'',status:r.published?'已发布':'草稿',stops:d.placeIds||[],poi:d.poiId||'',cover:d.mediaIds?.[0]||'',venue:d.placeId||'',date:d.startsAt?new Date(Date.parse(d.startsAt)+8*3600000).toISOString().slice(0,10):'',time:d.startsAt?new Date(Date.parse(d.startsAt)+8*3600000).toISOString().slice(11,16):'',eventStatus:d.status==='cancelled'?'取消':'正常举行'};}
 async function refresh(){records=await client.admin('content');artists=records.filter(r=>r.kind==='artist');places.splice(0,places.length,...records.filter(r=>r.kind==='place').map(translate));additionalRecords.splice(0,additionalRecords.length,...records.filter(r=>['route','event'].includes(r.kind)).map(translate));routeRecord=additionalRecords.find(r=>r.kind==='路线')||empty('route');eventRecord=additionalRecords.find(r=>r.kind==='演出')||empty('event');const raw=await client.admin('submissions');submissions.splice(0,submissions.length,...raw.map(s=>({id:s.id,kind:s.kind==='route'?'路线投稿':'地点补充',name:s.data.name,artist:artists.find(a=>a.id===s.artist_id)?.draft.name||'',city:s.data.city,status:{pending:'待审核',approved:'已通过',rejected:'需补充'}[s.status],source:s.data.source,note:s.reason||s.data.sameSpot||'',backend:s})));state.selectedSubmission=submissions[0]?.id||null;
  const images=await client.admin('media');for(const image of media)if(image.url?.startsWith('blob:'))URL.revokeObjectURL(image.url);media.splice(0);for(const image of images){media.push({id:image.id,name:'图片 '+image.id.slice(0,8),alt:'内容图片',type:'local',url:await client.imageUrl(image.id),source:image.visibility==='public'?'已发布的内容图片':'本机私有素材',verified:false});}
 }
 reviewPage=function(){if(!submissions.length)return header('投稿审核','管理员自建与用户投稿共用公开内容规则。')+'<section class="section"><p>暂无待审核投稿</p></section>';const s=submissions.find(s=>s.id===state.selectedSubmission),existing=s.backend.data.poiId?places.find(p=>p.poi===s.backend.data.poiId):null;return oldReview().replace('趵突泉 · 关联已有地点，不重复新建',esc(existing?existing.name+' · 复用已有地点':'新地点，审核后创建')).replace('六个地点引用，站点独立保存',(s.backend.data.placeIds?.length||0)+' 个地点引用，站点独立保存').replaceAll(' · 界面示例','').replace('选项仅用于操作演示，不代表参考资料已核验。','请核对原始资料后提交审核结果。').replace('通过审核（演示）','通过审核');};
 footer=function(){return `<footer class="edit-footer"><span class="save-state" id="save-state">${state.dirty?'尚未保存':uuidLike(state.draft?.id)?'已保存到本机数据库':'新草稿'}</span><div class="actions">${button('预览','preview','secondary')}${button('保存草稿','save','primary')}${button('发布检查','publish','secondary')}</div></footer>`;};
 checks=function(){return oldChecks().filter(c=>c.text!=='真实管理权限与存储待接入');};
 function value(d,kind){const v={name:d.name,city:d.city,source:d.source};if(uuidLike(d.id)){v.id=d.id;v.version=d.version;}if(uuidLike(d.cover))v.mediaIds=[d.cover];
  if(kind==='place'){Object.assign(v,{category:d.category||'其他',description:d.description||'',address:d.address||''});if(d.poi)v.poiId=d.poi;const artist=d.artist||d.importContext?.artist,evidenceSource=d.importContext?.source||d.source;if(artist)v.artistEvidence={artistId:artistId(artist),source:evidenceSource,sameSpot:d.same||d.importContext?.evidence||''};if(d.importContext?.source)v.source=d.importContext.source;if(Number.isFinite(d.longitude)&&Number.isFinite(d.latitude))Object.assign(v,{longitude:d.longitude,latitude:d.latitude,coordinateSystem:'gcj02'});}
  if(kind==='route')Object.assign(v,{artistId:artistId(d.artist),placeIds:d.stops,description:d.description||''});
  if(kind==='event'){if(!d.date||!d.time)throw Object.assign(Error(),{code:'INVALID_INPUT'});Object.assign(v,{artistIds:[artistId(d.artist)],placeId:d.venue,startsAt:new Date(d.date+'T'+d.time+':00+08:00').toISOString(),timeZone:'Asia/Shanghai',status:d.eventStatus==='取消'?'cancelled':'upcoming'});}return v;
 }
 render=function(){if(state.view==='place'&&!state.draft)state.draft=empty('place');window.START_ALLOWED_ARTISTS=artists.map(a=>a.draft.name);oldRender();document.querySelectorAll('select[data-field="artist"]').forEach(el=>{el.innerHTML='<option value="">请选择艺人</option>'+artists.map(a=>`<option ${a.draft.name===state.draft?.artist?'selected':''}>${esc(a.draft.name)}</option>`).join('');});if(state.view==='library'){const seen=new Set();document.querySelectorAll('.catalog-row').forEach(row=>{const id=row.querySelector('[data-edit]')?.dataset.edit;if(seen.has(id))row.remove();seen.add(id);});document.querySelector('#row-count').textContent=document.querySelectorAll('.catalog-row').length+' 条内容';}};
 async function persist(){const current=clone(state.draft),kind=state.view;if(!['place','route','event'].includes(kind))return;
  const pending=places.filter(p=>!uuidLike(p.id)&&((kind==='route'&&current.stops.includes(p.id))||(kind==='event'&&current.venue===p.id)||(lastTextBatch?.additions.some(a=>a.id===p.id))));
  if(pending.length){const items=pending.map(p=>{const v=value(p,'place');delete v.id;delete v.version;return v;}),imported=await client.command('import.places',{items});const ids=new Map(pending.map((p,i)=>[p.id,imported.ids[i]]));if(kind==='route')current.stops=current.stops.map(id=>ids.get(id)||id);if(kind==='event')current.venue=ids.get(current.venue)||current.venue;lastTextBatch=null;}
  const result=await client.command(kind+'.save',value(current,kind));await refresh();state.recordId=result.id;state.draft=translate(records.find(r=>r.id===result.id));state.dirty=false;render();document.querySelector('#save-state').textContent='已保存到本机数据库';setToast('已保存');}
 save=()=>locked(persist);
 setDirty=function(){state.dirty=true;document.querySelector('#save-state')?.replaceChildren(document.createTextNode('尚未保存'));};
 fileSelected=(file,cover)=>locked(async()=>{if(!file)return;const upload=await client.uploadImage(file);media.push({id:upload.id,name:file.name,alt:file.name,type:'local',url:URL.createObjectURL(file),source:'已存入本机私有媒体',verified:false});if(cover){state.draft.cover=upload.id;state.draft.photoAlt=file.name;setDirty();}render();setToast('图片已上传，发布前仅私有可见');});
 action=function(name,target){
  if(name==='publish')return locked(async()=>{if(state.dirty||!uuidLike(state.draft?.id)){setToast('请先保存草稿');return;}const d=state.draft;openDialog('发布检查',`<p>确认来源、图片使用权和内容无误后，发布到本机公开内容库。</p><div class="dialog-actions">${button('返回编辑','close','secondary')}${button('确认发布','local-publish','primary')}</div>`);});
  if(name==='local-publish')return locked(async()=>{const id=state.draft.id;await client.command('content.publish',{id,version:state.draft.version});dialogEl.close();await refresh();state.recordId=id;state.draft=translate(records.find(r=>r.id===id));render();setToast('已发布到本机内容库');});
  if(name==='approve'||name==='confirm-return')return locked(async()=>{const id=state.selectedSubmission;if(!id)return;const reason=name==='confirm-return'?document.querySelector('#return-reason')?.value.trim():undefined;if(name==='confirm-return'&&!reason){document.querySelector('#return-error').textContent='请填写退回原因';return;}await client.command('submission.review',{id,decision:name==='approve'?'approve':'reject',...(reason?{reason}:{}),...(name==='approve'?{checked:true}:{})});dialogEl.close();await refresh();render();setToast('审核结果已保存');});
  if(name==='review'&&!submissions.length){setToast('暂无待审核投稿');return;}
  return oldAction(name,target);
 };
 const placeholder=()=>{places.splice(0);additionalRecords.splice(0);submissions.splice(0);media.splice(0);state.view='library';state.draft=null;render();document.querySelector('.sidebar-foot').textContent='未登录';};
 (async()=>{mainEl.hidden=true;try{const api=await import('/client.mjs');client=api.createPlatformClient({getBearer:async()=>typeof window.START_GET_BEARER==='function'?window.START_GET_BEARER():null});await refresh();document.querySelector('.demo-banner span').textContent='本机数据库 · 不连接云环境';document.querySelector('.sidebar-foot').textContent='平台管理员 · 本地验收';fromHash();}catch(e){placeholder();setToast(msg(e));document.querySelector('.demo-banner span').textContent='登录能力尚未配置 · 当前只读';}finally{mainEl.hidden=false;window.START_LOCAL_READY=true;}})();
})();
